rows = load_rows("data/ledger.csv")

class _Tally:
    __slots__ = ("count", "total_cents", "max_cents", "regions")
    def __init__(self, amount, region):
        self.count = 1
        self.total_cents = amount
        self.max_cents = amount
        self.regions = {region: None}
    def add(self, amount, region):
        self.count += 1
        self.total_cents += amount
        if amount > self.max_cents:
            self.max_cents = amount
        if region not in self.regions:
            self.regions[region] = None

def v_class(rows):
    tallies = {}
    for row in rows:
        t = tallies.get(row.account)
        if t is None:
            tallies[row.account] = _Tally(row.amount_cents, row.region)
        else:
            t.add(row.amount_cents, row.region)
    return {a: AccountSummary(a, t.count, t.total_cents, t.max_cents, tuple(t.regions))
            for a, t in tallies.items()}

base = None
times = []
for _ in range(3):
    t0 = time.perf_counter(); r = v_class(rows); times.append(time.perf_counter() - t0)
print(f"class_tally  {min(times):.3f}s")
