import sys, time
sys.path.insert(0, "src")
from rollup import load_rows, AccountSummary
rows = load_rows("data/ledger.csv")

class T_dict:
    __slots__ = ("count", "total_cents", "max_cents", "regions")
    def __init__(self, amount, region):
        self.count = 1; self.total_cents = amount; self.max_cents = amount
        self.regions = {region: None}
    def add(self, amount, region):
        self.count += 1; self.total_cents += amount
        if amount > self.max_cents: self.max_cents = amount
        regs = self.regions
        if region not in regs: regs[region] = None

class T_list:
    __slots__ = ("count", "total_cents", "max_cents", "regions")
    def __init__(self, amount, region):
        self.count = 1; self.total_cents = amount; self.max_cents = amount
        self.regions = [region]
    def add(self, amount, region):
        self.count += 1; self.total_cents += amount
        if amount > self.max_cents: self.max_cents = amount
        regs = self.regions
        if region not in regs: regs.append(region)

def run(cls, use_try):
    tallies = {}
    if use_try:
        for row in rows:
            try:
                tallies[row.account].add(row.amount_cents, row.region)
            except KeyError:
                tallies[row.account] = cls(row.amount_cents, row.region)
    else:
        get = tallies.get
        for row in rows:
            t = get(row.account)
            if t is None:
                tallies[row.account] = cls(row.amount_cents, row.region)
            else:
                t.add(row.amount_cents, row.region)
    return {a: AccountSummary(a, t.count, t.total_cents, t.max_cents, tuple(t.regions))
            for a, t in tallies.items()}

base = None
for label, cls, use_try in [("dict_regions,get", T_dict, False),
                            ("dict_regions,try", T_dict, True),
                            ("list_regions,get", T_list, False)]:
    times = []
    for _ in range(5):
        t0 = time.perf_counter(); r = run(cls, use_try); times.append(time.perf_counter() - t0)
    if base is None: base = r
    print(f"{label:20s} min={min(times):.3f}s identical={r == base}")
